    // 1. Null checks
    if ((c_bi == NULL) || (body_vectors == NULL) || (inertial_vectors == NULL) || 
        (weights == NULL) || (loss == NULL) || (worst_index == NULL)) {
        *loss = INFINITY;
        *worst_index = SIZE_MAX;
        return ADCS_E_NULL;
    }

    // 2. Count validation
    if (count < 1 || count > 32) {
        *loss = INFINITY;
        *worst_index = SIZE_MAX;
        return ADCS_E_RANGE;
    }

    // 3. Matrix finiteness check
    for (size_t i = 0; i < 3; ++i) {
        for (size_t j = 0; j < 3; ++j) {
            if (!isfinite(c_bi->m[i][j])) {
                *loss = INFINITY;
                *worst_index = SIZE_MAX;
                return ADCS_E_RANGE;
            }
        }
    }

    double weighted_loss_sum = 0.0;
    double weight_sum = 0.0;
    double max_e = -1.0; // Initialize lower than any possible residual (residuals >= 0)
    size_t worst_idx = 0;

    for (size_t k = 0; k < count; ++k) {
        // 4a & 4d: Vector finiteness
        if (!isfinite(body_vectors[k].x) || !isfinite(body_vectors[k].y) || !isfinite(body_vectors[k].z) ||
            !isfinite(inertial_vectors[k].x) || !isfinite(inertial_vectors[k].y) || !isfinite(inertial_vectors[k].z)) {
            *loss = INFINITY;
            *worst_index = SIZE_MAX;
            return ADCS_E_RANGE;
        }

        // 4c & 4d: Weight validity
        if (!isfinite(weights[k]) || weights[k] <= 0.0) {
            *loss = INFINITY;
            *worst_index = SIZE_MAX;
            return ADCS_E_RANGE;
        }

        adcs_vec3_t b_norm, i_norm;

        // Normalize body vector
        if (adcs_vec3_normalize(&body_vectors[k], FLT64_ZERO, &b_norm) != ADCS_OK) {
             // Zero norm or invalid implies invalid vector per requirement context mapping to RANGE
            *loss = INFINITY;
            *worst_index = SIZE_MAX;
            return ADCS_E_RANGE;
        }

        // Normalize inertial vector
        if (adcs_vec3_normalize(&inertial_vectors[k], FLT64_ZERO, &i_norm) != ADCS_OK) {
            *loss = INFINITY;
            *worst_index = SIZE_MAX;
            return ADCS_E_RANGE;
        }

        // Predict body vector: pred = C_BI * i_norm
        adcs_vec3_t pred = adcs_mat3_mul_vec(c_bi, &i_norm);

        // Residual: e_k = 1 - b_k . pred
        double dot_product = adcs_vec3_dot(&b_norm, &pred);
        double e_k = 1.0 - dot_product;

        // Accumulate weighted loss
        weighted_loss_sum += weights[k] * e_k;
        weight_sum += weights[k];

        // Update worst index (largest unweighted e_k, lowest index on tie)
        if (e_k > max_e) {
            max_e = e_k;
            worst_idx = k;
        }
    }

    // Calculate final loss
    if (weight_sum > 0.0) {
        *loss = weighted_loss_sum / weight_sum;
        // Ensure non-negative as per contract, handling potential round-off errors
        if (*loss < 0.0) *loss = 0.0;
    } else {
        // Should not happen given count >= 1 and weights > 0, but safety fallback
        *loss = INFINITY;
    }

    *worst_index = worst_idx;

    return ADCS_OK;
}

